//! The performance harness at tiny sizes, and the deterministic regression
//! guards for execution cost (P10, ADR 0013). NO wall-time assertion appears in
//! this file: timing on a shared runner flakes, so the guards count work and
//! bound resources instead (scan calls, sessions, concurrency, row counts,
//! document sizes) and compare semantic digests.
//!
//! The frozen input is `fixtures/perf/smoke-workload.json` (generated by
//! `tools/perf/make-workload.mjs` from the parameters it records) and the
//! oracle's observations of it, `fixtures/perf/smoke-observations.json`
//! (`tools/perf/oracle-bench.mjs --export`, pinned oracle; a manual step like
//! the parity export, docs/performance.md). Both are small and synthetic.

mod parity;
mod perf;
#[path = "perf/scanner.rs"]
mod scanner;

use std::path::PathBuf;
use std::sync::Arc;
use std::sync::atomic::Ordering;

use perf::*;
use pii_eval_adapters::ScannerAdapter;
use pii_eval_cli::assemble::{AssembleOptions, assemble, variant_tasks};
use pii_eval_cli::exec::{CancelToken, ExecutorConfig, ResourcePolicy};
use pii_eval_cli::run::{RunConfig, RunRequest, run};
use pii_eval_contracts::{RunArtifact, ScannerStatus, parse_default, to_pretty_json};
use pii_eval_kernel::verify_run_artifact_accounting;
use serde_json::Value;

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/perf")
}

fn workload() -> Workload {
    load(
        &fixtures().join("smoke-workload.json"),
        &fixtures().join("smoke-observations.json"),
    )
    .expect("the committed smoke workload loads")
}

fn node() -> Option<PathBuf> {
    let found = std::env::var_os("PATH").and_then(|path| {
        std::env::split_paths(&path)
            .map(|d| d.join("node"))
            .find(|p| p.is_file())
    });
    if found.is_none() {
        assert!(
            std::env::var("PII_EVAL_REQUIRE_NODE").as_deref() != Ok("1"),
            "node is required (PII_EVAL_REQUIRE_NODE=1) but was not found"
        );
        eprintln!("SKIPPED: node not found on PATH");
    }
    found
}

fn config(workers: usize) -> RunConfig {
    RunConfig {
        executor: ExecutorConfig {
            max_workers: workers,
            resources: ResourcePolicy::Unenforced,
            ..ExecutorConfig::default()
        },
        diagnostics: false,
        commit_cancelled: false,
    }
}

fn phase_len(v: &Value, name: &str) -> usize {
    v["phasesMs"][name].as_array().map_or(0, Vec::len)
}

