#[test]
fn the_committed_workload_is_what_its_generator_produces() {
    let Some(node) = node() else { return };
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    let params = std::fs::read_to_string(fixtures().join("smoke-workload.json")).unwrap();
    let params: Value = serde_json::from_str(&params).unwrap();
    let w = serde_json::to_string(&params["workload"]).unwrap();
    let out = std::process::Command::new(node)
        .arg(root.join("tools/perf/make-workload.mjs"))
        .arg("--check")
        .arg(&w)
        .output()
        .expect("node runs");
    assert!(out.status.success(), "the generator failed");
    let reported: Value = serde_json::from_slice(&out.stdout).unwrap();
    let file = std::fs::read(fixtures().join("smoke-workload.json")).unwrap();
    assert_eq!(
        reported["digest"].as_str().unwrap(),
        sha256_hex(&file),
        "fixtures/perf/smoke-workload.json is not what tools/perf/make-workload.mjs generates from its recorded parameters"
    );
}

#[test]
fn observations_must_belong_to_the_workload() {
    let tmp = std::env::temp_dir().join(format!("pii-eval-perf-bind-{}", std::process::id()));
    std::fs::create_dir_all(&tmp).unwrap();
    let mut obs: Value =
        serde_json::from_slice(&std::fs::read(fixtures().join("smoke-observations.json")).unwrap())
            .unwrap();
    obs["workloadSha256"] = Value::String("0".repeat(64));
    let path = tmp.join("obs.json");
    std::fs::write(&path, serde_json::to_vec(&obs).unwrap()).unwrap();
    let err = load(&fixtures().join("smoke-workload.json"), &path)
        .err()
        .expect("a mismatched binding is refused");
    assert!(err.contains("another workload"), "{err}");
    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn every_measurement_runs_at_a_tiny_size_and_reports_what_it_promises() {
    let w = workload();
    let tmp = std::env::temp_dir().join(format!("pii-eval-perf-smoke-{}", std::process::id()));
    std::fs::create_dir_all(&tmp).unwrap();

    let g = measure_generate(&w, 2);
    assert_eq!(g["variants"], 41);
    assert_eq!(phase_len(&g, "generate"), 2);

    let r = measure_replay(&w, 2, &tmp);
    assert_eq!(r["counts"]["cases"], 24);
    assert_eq!(r["counts"]["variants"], 41);
    assert_eq!(r["counts"]["scanners"], 2);
    assert_eq!(r["counts"]["findings"], 235);
    // one occurrence per variant and scanner
    assert_eq!(r["rows"], 82);
    for phase in [
        "assemble",
        "assembleKernel",
        "verify",
        "validate",
        "serialize",
        "parse",
    ] {
        assert_eq!(phase_len(&r, phase), 2, "{phase}");
    }
    assert_eq!(phase_len(&r, "writer"), 1);

    // The oracle-faithful path agrees with the oracle's own metric counts.
    let c = measure_compat(&w, 1);
    assert_eq!(c["equalToOracleCounts"], true);

    let e = measure_engine(&w, 1, 3, 2, 2, 2);
    assert_eq!(e["counts"]["variants"], 41);
    assert_eq!(e["phasesMs"]["scanCalls"][0], 2.0 * 41.0 * 2.0);

    let p = measure_prepare(&w);
    assert_eq!(p["counts"]["variants"], 41);
    let _ = std::fs::remove_dir_all(&tmp);
}

// ---------------------------------------------------------------------------
// Deterministic guards: counters and bounds, never timings
// ---------------------------------------------------------------------------

#[test]
fn the_executor_performs_exactly_the_planned_work_within_its_bounds() {
    let w = workload();
    let p = prepare(&w);
    let scanners = p.counts.scanners;
    let variants = p.counts.variants;
    for (workers, per_scanner, replays) in [(1u32, 1u32, 2u32), (4, 2, 2), (8, 8, 3), (3, 3, 3)] {
        let manifest = manifest_of(&p, workers, 2, per_scanner, replays);
        pii_eval_contracts::validate(&manifest)
            .unwrap_or_else(|e| panic!("manifest ({workers},{per_scanner},{replays}): {e:?}"));
        let adapters = replay_adapters(&p);
        let gauges: Vec<_> = adapters
            .iter()
            .map(|a| {
                (
                    Arc::clone(&a.scans),
                    Arc::clone(&a.sessions),
                    Arc::clone(&a.live),
                    Arc::clone(&a.max_live),
                )
            })
            .collect();
        let out = run(
            &RunRequest {
                snapshot: &p.snapshot,
                manifest: &manifest,
                adapters: adapters
                    .into_iter()
                    .map(|a| Arc::new(a) as Arc<dyn ScannerAdapter>)
                    .collect(),
            },
            &config(workers as usize),
            &CancelToken::new(),
        )
        .expect("the run");
        let mut peak_total = 0;
        for (scans, sessions, live, max_live) in &gauges {
            // Every variant is scanned once per replay pass, by exactly one worker.
            assert_eq!(
                scans.load(Ordering::SeqCst),
                variants * u64::from(replays),
                "scan calls (workers {workers}, replays {replays})"
            );
            // At most `per_scanner` sessions are alive at once, and none leaks.
            assert!(max_live.load(Ordering::SeqCst) <= u64::from(per_scanner));
            assert_eq!(live.load(Ordering::SeqCst), 0, "every session was closed");
            // A fresh session per replay pass and worker, never more.
            assert!(sessions.load(Ordering::SeqCst) <= u64::from(replays * per_scanner));
            assert!(sessions.load(Ordering::SeqCst) >= u64::from(replays));
            peak_total += max_live.load(Ordering::SeqCst);
        }
        // The whole run never exceeds the effective worker bound.
        assert!(peak_total <= u64::from(workers) * scanners);
        assert!(out.effective.workers <= workers as usize);
        assert_eq!(
            out.assembled.artifact.semantic.outcomes.len() as u64,
            scanners * variants
        );
    }
}

#[test]
fn execution_and_replay_agree_and_the_host_worker_cap_changes_nothing_semantic() {
    let w = workload();
    let p = prepare(&w);
    // One manifest; only the HOST cap varies, as the CLI's `host.maxWorkers` does.
    let manifest = manifest_of(&p, 8, 2, 4, 2);
    let digests: Vec<(String, Vec<String>)> = [1usize, 2, 3, 8, 64]
        .into_iter()
        .map(|cap| {
            let adapters = replay_adapters(&p)
                .into_iter()
                .map(|a| Arc::new(a) as Arc<dyn ScannerAdapter>)
                .collect();
            let out = run(
                &RunRequest {
                    snapshot: &p.snapshot,
                    manifest: &manifest,
                    adapters,
                },
                &config(cap),
                &CancelToken::new(),
            )
            .expect("the run");
            (
                out.assembled.artifact.semantic_digest.as_str().to_owned(),
                out.assembled
                    .observations
                    .iter()
                    .map(|o| o.semantic_digest.as_str().to_owned())
                    .collect(),
            )
        })
        .collect();
    assert!(digests.windows(2).all(|w| w[0] == w[1]), "{digests:?}");

    // Replaying the frozen observations through `assemble` (no executor, no scanner)
    // gives the same documents as executing them.
    let runs = frozen_runs(&p, manifest.semantic.mechanics.replays);
    let assembled = assemble(
        &p.snapshot,
        &manifest,
        &variant_tasks(&p.snapshot),
        &runs,
        AssembleOptions {
            diagnostics: false,
            run_started_at: std::time::SystemTime::UNIX_EPOCH,
        },
    )
    .expect("assembles");
    assert_eq!(assembled.artifact.semantic_digest.as_str(), digests[0].0);
    assert_eq!(
        assembled
            .observations
            .iter()
            .map(|o| o.semantic_digest.as_str().to_owned())
            .collect::<Vec<_>>(),
        digests[0].1
    );
    // ... and the artifact verifies, serializes, and parses back to itself.
    verify_run_artifact_accounting(&assembled.artifact, &p.snapshot).expect("verifies");
    let text = to_pretty_json(&assembled.artifact).unwrap();
    let back: RunArtifact = parse_default(text.as_bytes()).expect("parses back");
    assert_eq!(back.semantic_digest, assembled.artifact.semantic_digest);
    assert!(
        assembled
            .artifact
            .semantic
            .scanners
            .iter()
            .all(|s| s.status == ScannerStatus::Complete)
    );
}

#[test]
fn repeated_runs_are_byte_identical() {
    let w = workload();
    let a = measure_replay(&w, 1, &std::env::temp_dir());
    let b = measure_replay(&w, 1, &std::env::temp_dir());
    assert_eq!(a["fingerprint"], b["fingerprint"]);
    assert_eq!(a["artifactBytes"], b["artifactBytes"]);
    assert_eq!(a["observationBytes"], b["observationBytes"]);
}

#[test]
fn the_full_pipeline_runs_through_the_built_binary_over_the_inert_fake() {
    let Some(node) = node() else { return };
    let w = workload();
    let tmp = std::env::temp_dir().join(format!("pii-eval-perf-cli-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../pii-eval-adapters/tests/fixtures/fake-core");
    let doc = scanner::emit_cli(&w, &tmp, &package, "candidate", 2, 2);
    assert_eq!(doc["variants"], 41);
    let out = std::process::Command::new(env!("CARGO_BIN_EXE_pii-eval"))
        .arg("run")
        .arg("--config")
        .arg(tmp.join("run-config.json"))
        .arg("--node")
        .arg(&node)
        .arg("--out")
        .arg(tmp.join("out"))
        .output()
        .expect("the binary runs");
    assert!(
        out.status.success(),
        "the CLI failed: {}",
        String::from_utf8_lossy(&out.stdout)
    );
    let artifact: Value =
        serde_json::from_slice(&std::fs::read(tmp.join("out/run-artifact.json")).unwrap()).unwrap();
    // Diagnostics are on: the phases the report separates are all recorded.
    let phases: Vec<&str> = artifact["diagnostics"]["phases"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| p["phase"].as_str().unwrap())
        .collect();
    for want in [
        "kernel-replay",
        "materialization",
        "scan",
        "scanner-startup",
        "serialization",
        "total",
    ] {
        assert!(phases.contains(&want), "{want}");
    }
    let _ = std::fs::remove_dir_all(&tmp);
}

/// `replay` of a sanitized-output scanner's observations looks every variant up by its task index
/// (the lookup ADR 0013 made O(1)). The replayed documents must carry the same semantic digests as
/// the run that produced the observations, and they cannot be produced without the original
/// artifact, which proves the sanitized-output verdict path ran.
#[test]
fn replay_of_a_sanitized_output_run_reproduces_the_run() {
    let Some(node) = node() else { return };
    let w = workload();
    let tmp = std::env::temp_dir().join(format!("pii-eval-perf-replay-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../pii-eval-adapters/tests/fixtures/fake-core");
    scanner::emit_cli(&w, &tmp, &package, "candidate", 2, 2);
    let bin = env!("CARGO_BIN_EXE_pii-eval");
    let ran = std::process::Command::new(bin)
        .args(["run", "--config"])
        .arg(tmp.join("run-config.json"))
        .arg("--node")
        .arg(&node)
        .arg("--out")
        .arg(tmp.join("orig"))
        .output()
        .expect("run");
    assert!(ran.status.success());
    let observation = tmp.join("orig/observation-redact-secret-core.json");
    let replay = |extra: &[&std::ffi::OsStr], out: &str| {
        std::process::Command::new(bin)
            .args(["replay", "--snapshot"])
            .arg(tmp.join("snapshot.json"))
            .arg("--manifest")
            .arg(tmp.join("orig/manifest.json"))
            .arg("--observation")
            .arg(&observation)
            .args(extra)
            .arg("--out")
            .arg(tmp.join(out))
            .output()
            .expect("replay")
    };
    // Without the original a sanitized-output scanner cannot be replayed (exit 3, replay-original-required).
    let alone = replay(&[], "alone");
    assert_eq!(alone.status.code(), Some(3), "replay needs the original");
    let original = tmp.join("orig/run-artifact.json");
    let again = replay(&["--original".as_ref(), original.as_os_str()], "again");
    assert!(
        again.status.success(),
        "{}",
        String::from_utf8_lossy(&again.stdout)
    );
    let digest = |p: &str| -> String {
        let v: Value = serde_json::from_slice(&std::fs::read(tmp.join(p)).unwrap()).unwrap();
        v["semanticDigest"].as_str().unwrap().to_owned()
    };
    assert_eq!(
        digest("orig/run-artifact.json"),
        digest("again/run-artifact.json")
    );
    assert_eq!(
        digest("orig/observation-redact-secret-core.json"),
        digest("again/observation-redact-secret-core.json")
    );
    assert_eq!(
        digest("orig/public-synthetic-artifact.json"),
        digest("again/public-synthetic-artifact.json")
    );
    let _ = std::fs::remove_dir_all(&tmp);
}
